-- NAYORA : profil adaptatif propre à chaque univers (objectif → questions
-- suivantes : domaines, stade, contrat, intérêts, destinations, compétences…).
-- Voir src/lib/universe-match.ts (UNIVERSE_FORMS) pour le schéma.
alter table profiles add column if not exists universe_data jsonb not null default '{}'::jsonb;

-- Profils de démonstration : un parcours par univers, avec des objectifs
-- complémentaires entre eux (Marc mentor ↔ Sofiane cherche un mentor, Ibrahim
-- recrute ↔ …, Amina guide à Abidjan ↔ Sofiane cherche un guide, Nadia porteuse ↔ Léa rejoint).
update profiles set universes = 'mariage,amitie', universe_data = '{"loveHorizon":"1an","friendGoal":"cercle","interests":["cuisine","musique","culture"],"groupFormat":"petit","loveGoal":"mariage","hasChildren":"none","wantsChildren":"yes","religion":"musulman","faithPractice":"pratiquant","religionImportance":"souhaite","polygamy":"non","values":["foi","famille","respect"],"partnerValues":["respect","fidelite"],"partnerAgeMin":28,"partnerAgeMax":38,"partnerMinHeight":172,"lookingForText":"Un homme sérieux, respectueux et attaché à sa famille, pour une relation aboutissant au mariage."}'::jsonb where user_id = 'demo-elena';
update profiles set universes = 'professionnel,projets', universe_data = '{"proGoal":"mentor_offre","focusDomains":["tech"],"proExperience":"10","projectRole":"transmettre","skillsOffer":["tech"],"learnFormat":"en_ligne"}'::jsonb where user_id = 'demo-marc';
update profiles set universes = 'mariage,voyage', universe_data = '{"loveHorizon":"1an","travelGoal":"guide","travelStyles":["culture","gastronomie"],"travelDestinations":["CI"],"loveGoal":"mariage","hasChildren":"none","wantsChildren":"yes","religion":"protestant","faithPractice":"pratiquant","religionImportance":"essentiel","polygamy":"non","values":["foi","honnetete"],"partnerValues":["foi","fidelite"],"partnerAgeMin":30,"partnerAgeMax":38,"lookingForText":"Un homme protestant ayant la crainte de Dieu, pour un mariage."}'::jsonb where user_id = 'demo-amina';
update profiles set universes = 'mariage,professionnel', universe_data = '{"loveHorizon":"1an","proGoal":"affaires","focusDomains":["commerce"],"bizSide":"fournisseurs","loveGoal":"mariage","hasChildren":"one","wantsChildren":"open","religion":"protestant","faithPractice":"croyant","religionImportance":"souhaite","polygamy":"non","values":["famille","ambition"],"partnerValues":["foi","respect"],"partnerAgeMin":27,"partnerAgeMax":36}'::jsonb where user_id = 'demo-yann';
update profiles set universes = 'professionnel,projets', universe_data = '{"proGoal":"associe","focusDomains":["agriculture"],"proStage":"idee","proNeed":["competences","financement"],"projectRole":"porteur","projectDomain":"agriculture","projectStage":"idee","skillsWant":["tech"]}'::jsonb where user_id = 'demo-nadia';
update profiles set universes = 'amitie,voyage', universe_data = '{"interests":["sport","musique","jeux"],"friendGoal":"activites","availability":["weekend","soir"],"travelGoal":"compagnon","travelStyles":["aventure","roadtrip"],"travelDestinations":["GH","BJ"],"travelWhen":"flex","travelBudget":"eco"}'::jsonb where user_id = 'demo-ken';
update profiles set universes = 'amitie,projets', universe_data = '{"interests":["nature","lecture","benevolat"],"friendGoal":"communaute","communityType":"association","projectRole":"rejoindre","skillsOffer":["tech"],"projectDomain":"agriculture","projectCommit":"5h"}'::jsonb where user_id = 'demo-lea';
update profiles set universes = 'professionnel,voyage', universe_data = '{"proGoal":"mentor_cherche","focusDomains":["tech"],"proLevel":"debutant","travelGoal":"chercher_guide","travelStyles":["culture","festival"],"travelDestinations":["CI","SN"],"travelWhen":"annee"}'::jsonb where user_id = 'demo-sofiane';
update profiles set universes = 'mariage,projets', universe_data = '{"loveHorizon":"sans_pression","projectRole":"apprendre","skillsWant":["tech"],"learnFormat":"en_ligne","loveGoal":"serieuse","hasChildren":"none","religion":"sans_religion","religionImportance":"indifferent","values":["humour","honnetete"],"partnerValues":["respect","humour"]}'::jsonb where user_id = 'demo-ines';
update profiles set universes = 'professionnel,voyage', universe_data = '{"proGoal":"recrute","focusDomains":["tech","finance"],"contractTypes":["freelance","cdi"],"travelGoal":"compagnon","travelStyles":["aventure","detente"],"travelDestinations":["MA"],"travelWhen":"3m","travelBudget":"confort"}'::jsonb where user_id = 'demo-ibrahim';
